insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values
('KR:chef','2026-08-10',0,0,0,0,10,0,0,0,5,15,'career-opportunity-kr-v1','provisional',jsonb_build_object('classification_scope','KECO 2025 5311 주방장 및 요리 연구가 is restricted here to chef/kitchen-leadership work.','entry_level_basis','Chef roles normally require progression from practical kitchen work; the reviewed degree is related rather than an appointment guarantee.','qualification_note','No universal chef licence is assigned, while specified food-service settings can require a licensed 조리사 under the Food Sanitation Act.','market_scope','Exact recurring chef vacancy, salary, shortage and growth evidence is not yet normalised.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('KR:cook','2026-08-10',0,0,0,0,15,0,0,0,4,19,'career-opportunity-kr-v1','provisional',jsonb_build_object('classification_scope','Cook spans KECO 5312, 5313, 5314, 5315, 5318 and 5319; no fabricated generic code is used.','entry_level_basis','Practical and vocational entry is relatively accessible.','qualification_note','The broad occupation is not universally licensed, but specified institutional food-service settings can require a licensed 조리사.','market_scope','Multiple cooking codes are not aggregated into a synthetic exact market series.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('KR:hotel-manager','2026-08-10',0,0,0,0,10,0,0,0,5,15,'career-opportunity-kr-v1','provisional',jsonb_build_object('classification_scope','Hotel management is a restricted subset of broader KECO 0141.','entry_level_basis','A reviewed Hospitality Management degree is direct study evidence, but operational experience is normally required for management appointment.','market_scope','Broad 0141 observations are not treated as hotel-manager-only evidence.','visa_scope','No occupation-specific visa credit is assigned.','score_scope','Entry structure and low universal licensing burden only.'),'2026-08-10'),
('KR:restaurant-manager','2026-08-10',0,0,0,0,10,0,0,0,5,15,'career-opportunity-kr-v1','provisional',jsonb_build_object('classification_scope','KECO 2025 0142 음식 서비스 관련 관리자 is the direct management family.','entry_level_basis','Hospitality study is related and management progression usually requires operational experience.','market_scope','Exact recurring 0142 vacancy, salary, shortage and growth evidence is not yet normalised.','visa_scope','No occupation-specific visa credit is assigned.','score_scope','Entry and burden only.'),'2026-08-10'),
('KR:baker','2026-08-10',0,0,0,0,15,0,0,0,5,20,'career-opportunity-kr-v1','provisional',jsonb_build_object('classification_scope','KECO 2025 8711 제과원 및 제빵사 is a direct mapping.','entry_level_basis','Vocational qualification, workplace training and related culinary study support accessible entry.','market_scope','Exact recurring 8711 vacancy, salary, shortage and growth evidence is not yet normalised.','visa_scope','No occupation-specific visa credit is assigned.','score_scope','Entry accessibility and low universal licensing burden only.'),'2026-08-10'),
('KR:tourism-manager','2026-08-10',0,0,0,0,10,0,0,0,5,15,'career-opportunity-kr-v1','provisional',jsonb_build_object('classification_scope','Tourism management is a restricted subset of broader KECO 0141; frontline travel service code 5211 is not substituted for management.','entry_level_basis','One direct Tourism & Convention programme and two related hospitality/tourism programmes are retained.','market_scope','Broad 0141 demand is not presented as tourism-manager-only evidence.','visa_scope','No occupation-specific visa credit is assigned.','score_scope','Entry and burden only.'),'2026-08-10'),
('KR:event-planner','2026-08-10',0,0,0,0,15,0,0,0,5,20,'career-opportunity-kr-v1','provisional',jsonb_build_object('classification_scope','KECO 2025 0244 행사·전시 및 회의 기획자 is a direct mapping.','entry_level_basis','One direct Tourism & Convention programme plus related hospitality, culture and tourism study support project-based entry.','market_scope','Exact recurring 0244 market evidence is not yet normalised.','visa_scope','No occupation-specific visa credit is assigned.','score_scope','Entry accessibility and low licensing burden only.'),'2026-08-10'),
('KR:hospitality-supervisor','2026-08-10',0,0,0,0,13,0,0,0,5,18,'career-opportunity-kr-v1','provisional',jsonb_build_object('classification_scope','No single KECO unit group covers cross-venue hospitality supervisors; 0141, 0142, 5230 and 5322 are kept only as reference specialisations.','entry_level_basis','A reviewed Hospitality Management programme is direct study evidence and frontline experience supports progression.','market_scope','Hotel, restaurant and frontline service series are not combined into a synthetic supervisor market figure.','visa_scope','No occupation-specific visa credit is assigned.','score_scope','Moderate entry credit and low universal licensing burden only.'),'2026-08-10')
